import { test, expect } from '@playwright/test';

test.describe('Order Summary Before Payment Confirmation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display order summary with correct details before payment confirmation', async ({ page }) => {
    // Verify order summary container is visible
    const summaryContainer = page.getByRole('region', { name: /order summary/i });
    await expect(summaryContainer).toBeVisible();

    // Verify summary title is present
    const summaryTitle = page.getByRole('heading', { name: /order summary/i });
    await expect(summaryTitle).toBeVisible();

    // Verify order details are displayed
    const orderDetails = page.getByRole('region', { name: /order details/i });
    await expect(orderDetails).toBeVisible();

    // Verify item list is displayed
    const itemList = page.getByRole('list', { name: /items/i });
    await expect(itemList).toBeVisible();

    // Verify item details are displayed
    const itemName = page.getByRole('heading', { name: /item name/i });
    await expect(itemName).toBeVisible();

    const itemPrice = page.getByRole('heading', { name: /item price/i });
    await expect(itemPrice).toBeVisible();

    // Verify total price is displayed
    const totalPrice = page.getByRole('heading', { name: /total price/i });
    await expect(totalPrice).toBeVisible();

    // Verify shipping address is displayed
    const shippingAddress = page.getByRole('region', { name: /shipping address/i });
    await expect(shippingAddress).toBeVisible();

    // Verify payment options are displayed
    const paymentOptions = page.getByRole('region', { name: /payment options/i });
    await expect(paymentOptions).toBeVisible();

    // Verify confirm button is visible
    const confirmButton = page.getByRole('button', { name: /confirm order/i });
    await expect(confirmButton).toBeVisible();

    // Verify cancel button is visible
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await expect(cancelButton).toBeVisible();

    // Verify order summary is visible and contains correct data
    const summaryText = page.getByText(/order summary/i);
    await expect(summaryText).toBeVisible();

    // Verify order details contain correct information
    const itemNameText = page.getByText(/item name/i);
    await expect(itemNameText).toBeVisible();

    const itemPriceText = page.getByText(/item price/i);
    await expect(itemPriceText).toBeVisible();

    // Verify total price is correct
    const totalPriceText = page.getByText(/total price/i);
    await expect(totalPriceText).toBeVisible();

    // Verify shipping address is correct
    const shippingAddressText = page.getByText(/shipping address/i);
    await expect(shippingAddressText).toBeVisible();

    // Verify payment options are available
    const paymentOptionText = page.getByText(/payment options/i);
    await expect(paymentOptionText).toBeVisible();

    // Verify confirm button is enabled
    await expect(confirmButton).toBeEnabled();

    // Verify cancel button is enabled
    await expect(cancelButton).toBeEnabled();
  });

  test('should handle edge case where order summary is empty', async ({ page }) => {
    // Navigate to checkout page
    await page.goto('/checkout');

    // Mock API response to return empty order summary
    await page.route('**/api/order-summary', (route) => {
      route.abort('failed to load');
    });

    // Verify order summary container is empty
    const summaryContainer = page.getByRole('region', { name: /order summary/i });
    await expect(summaryContainer).toHaveClass(/empty/);

    // Verify summary title is not visible
    const summaryTitle = page.getByRole('heading', { name: /order summary/i });
    await expect(summaryTitle).not.toBeVisible();

    // Verify no item details are displayed
    const itemList = page.getByRole('list', { name: /items/i });
    await expect(itemList).not.toBeVisible();

    // Verify no total price is displayed
    const totalPrice = page.getByRole('heading', { name: /total price/i });
    await expect(totalPrice).not.toBeVisible();

    // Verify shipping address is not displayed
    const shippingAddress = page.getByRole('region', { name: /shipping address/i });
    await expect(shippingAddress).not.toBeVisible();

    // Verify payment options are still available
    const paymentOptionText = page.getByText(/payment options/i);
    await expect(paymentOptionText).toBeVisible();

    // Verify confirm button is still visible
    const confirmButton = page.getByRole('button', { name: /confirm order/i });
    await expect(confirmButton).toBeVisible();

    // Verify cancel button is still visible
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await expect(cancelButton).toBeVisible();

    // Verify user is prompted to enter order details
    const orderDetailsPrompt = page.getByText(/please enter order details/i);
    await expect(orderDetailsPrompt).toBeVisible();

    // Verify user can enter order details
    const orderDetailsInput = page.getByLabel(/order details/i);
    await expect(orderDetailsInput).toBeVisible();

    // Verify user can proceed with empty order
    await confirmButton.click();

    // Verify user is redirected to order summary page
    const orderSummaryPage = page.getByRole('main', { name: /order summary/i });
    await expect(orderSummaryPage).toBeVisible();

    // Verify user is able to edit and save order
    const editButton = page.getByRole('button', { name: /edit order/i });
    await expect(editButton).toBeVisible();

    // Verify user can save changes
    await editButton.click();

    // Verify order summary is updated
    const updatedSummaryText = page.getByText(/updated order summary/i);
    await expect(updatedSummaryText).toBeVisible();

    // Verify user is redirected to confirmation page
    const confirmationPage = page.getByRole('main', { name: /confirm order/i });
    await expect(confirmationPage).toBeVisible();

    // Verify user can proceed with payment
    await confirmButton.click();

    // Verify payment page is displayed
    const paymentPage = page.getByRole('main', { name: /payment page/i });
    await expect(paymentPage).toBeVisible();

    // Verify user can complete payment
    await confirmButton.click();

    // Verify user is redirected to success page
    const successPage = page.getByRole('main', { name: /success/i });
    await expect(successPage).toBeVisible();
  });
});
